#include <locale>
#include <fmt/format.h>
struct us_punct : std::numpunct<char> {
  char do_decimal_point() const override { return '.'; }
  char do_thousands_sep() const override { return ','; }
  std::string do_grouping() const override { return "\3"; }
};
int main() {
  auto loc = std::locale(std::locale::classic(), new us_punct());
  for (double value : {-119.921, 2194.139, -57.639, -5.980, -2.119, 0.295, 1.295}) {
    auto text = fmt::format(loc, "{:19.3Lf}", value);
    fmt::print("value={} width={} |{}|\n", value, text.size(), text);
  }
}
