--- a/test/xchar-test.cc
+++ b/test/xchar-test.cc
@@ -440,6 +440,45 @@
   EXPECT_EQ(fmt::format(loc, "{:8L}", 1230.0), "   1~230");
 }

+TEST(locale_test, localized_double_alignment) {
+  auto loc = std::locale(std::locale::classic(), new numpunct<char>());
+  auto wloc = std::locale(std::locale::classic(), new numpunct<wchar_t>());
+  struct test_case {
+    double value;
+    const char* expected;
+  };
+  const test_case cases[] = {{-119.921, "-119?921"},
+                             {2194.139, "2~194?139"},
+                             {-57.639, "-57?639"},
+                             {-5.980, "-5?980"},
+                             {-2.119, "-2?119"},
+                             {0.295, "0?295"},
+                             {1.295, "1?295"},
+                             {0.0295, "0?030"},
+                             {0.0, "0?000"},
+                             {1234.0, "1~234?000"}};
+  for (auto test : cases) {
+    SCOPED_TRACE(test.value);
+    auto expected = std::string(test.expected);
+    auto padding = 19 - expected.size();
+    EXPECT_EQ(std::string(padding, ' ') + expected,
+              fmt::format(loc, "{:19.3Lf}", test.value));
+    EXPECT_EQ(expected + std::string(padding, ' '),
+              fmt::format(loc, "{:<19.3Lf}", test.value));
+    EXPECT_EQ(std::string(padding / 2, ' ') + expected +
+                  std::string(padding - padding / 2, ' '),
+              fmt::format(loc, "{:^19.3Lf}", test.value));
+    auto wexpected = std::wstring(expected.begin(), expected.end());
+    EXPECT_EQ(std::wstring(padding, L' ') + wexpected,
+              fmt::format(wloc, L"{:19.3Lf}", test.value));
+  }
+  EXPECT_EQ("             1?2345", fmt::format(loc, "{:19L}", 1.2345));
+  EXPECT_EQ(L"             1?2345", fmt::format(wloc, L"{:19L}", 1.2345));
+  EXPECT_EQ("              1?295", fmt::format(loc, "{:19.3Lf}", 1.295f));
+  EXPECT_EQ("              1?295", fmt::format(loc, "{:19.3Lf}", 1.295L));
+}
+
